// HookStateMachine.ts
// 黄金矿工钩子状态机实现

export enum HookState {
  IDLE = 'IDLE',           // 空闲状态 - 钩子在顶部摆动
  AIMING = 'AIMING',       // 瞄准状态 - 玩家控制角度
  EXTENDING = 'EXTENDING', // 伸出状态 - 钩子向下/向外延伸
  GRABBING = 'GRABBING',   // 抓取状态 - 钩住物品
  RETRACTING = 'RETRACTING', // 回收状态 - 钩子带着物品返回
  COOLDOWN = 'COOLDOWN'    // 冷却状态 - 抓取后的短暂冷却
}

export interface Position {
  x: number;
  y: number;
}

export interface HookConfig {
  maxLength: number;      // 最大延伸长度
  extendSpeed: number;    // 伸出速度
  retractSpeedBase: number; // 基础回收速度
  swingSpeed: number;     // 摆动速度
  swingAngleRange: number; // 摆动角度范围（度）
  cooldownDuration: number; // 冷却时间（毫秒）
}

export interface GrabbedItem {
  id: string;
  type: string;
  weight: number;         // 重量（影响回收速度）
  value: number;          // 价值
  position: Position;
}

export interface HookStateData {
  state: HookState;
  position: Position;     // 钩子当前位置
  angle: number;          // 当前角度（度）
  length: number;         // 当前绳索长度
  grabbedItem: GrabbedItem | null;
  stateStartTime: number; // 状态开始时间戳
  swingDirection: 1 | -1; // 摆动方向
}

export type StateTransition = {
  from: HookState;
  to: HookState;
  condition: string;
  action?: string;
};

export class HookStateMachine {
  private state: HookState;
  private stateData: HookStateData;
  private config: HookConfig;
  private origin: Position;  // 钩子起点（矿工位置）
  private stateListeners: Array<(from: HookState, to: HookState, data: HookStateData) => void>;

  // 状态转换表
  private static readonly TRANSITIONS: StateTransition[] = [
    { from: HookState.IDLE, to: HookState.EXTENDING, condition: 'player_trigger', action: 'start_extend' },
    { from: HookState.EXTENDING, to: HookState.GRABBING, condition: 'hit_item', action: 'grab_item' },
    { from: HookState.EXTENDING, to: HookState.RETRACTING, condition: 'max_length_or_hit_ground', action: 'start_retract' },
    { from: HookState.GRABBING, to: HookState.RETRACTING, condition: 'item_grabbed', action: 'start_retract_with_item' },
    { from: HookState.RETRACTING, to: HookState.COOLDOWN, condition: 'returned_to_origin', action: 'collect_item' },
    { from: HookState.COOLDOWN, to: HookState.IDLE, condition: 'cooldown_complete', action: 'reset' },
    // 特殊转换：任何状态都可以重置到IDLE
    { from: HookState.AIMING, to: HookState.EXTENDING, condition: 'player_trigger', action: 'start_extend' }
  ];

  constructor(origin: Position, config: Partial<HookConfig> = {}) {
    this.origin = origin;
    this.config = {
      maxLength: 300,
      extendSpeed: 5,
      retractSpeedBase: 8,
      swingSpeed: 2,
      swingAngleRange: 60,
      cooldownDuration: 500,
      ...config
    };

    this.state = HookState.IDLE;
    this.stateData = {
      state: HookState.IDLE,
      position: { ...origin },
      angle: -90, // 初始垂直向下
      length: 0,
      grabbedItem: null,
      stateStartTime: Date.now(),
      swingDirection: 1
    };

    this.stateListeners = [];
  }

  // 获取当前状态
  public getState(): HookState {
    return this.state;
  }

  public getStateData(): HookStateData {
    return { ...this.stateData };
  }

  // 订阅状态变化
  public onStateChange(callback: (from: HookState, to: HookState, data: HookStateData) => void): void {
    this.stateListeners.push(callback);
  }

  // 触发状态变化事件
  private emitStateChange(from: HookState, to: HookState): void {
    this.stateListeners.forEach(listener => listener(from, to, this.stateData));
  }

  // 状态转换
  private transitionTo(newState: HookState): void {
    const oldState = this.state;
    this.state = newState;
    this.stateData.state = newState;
    this.stateData.stateStartTime = Date.now();
    this.emitStateChange(oldState, newState);
  }

  // 玩家触发 - 发射钩子
  public trigger(): boolean {
    if (this.state === HookState.IDLE || this.state === HookState.AIMING) {
      this.transitionTo(HookState.EXTENDING);
      return true;
    }
    return false;
  }

  // 抓取到物品
  public grabItem(item: GrabbedItem): boolean {
    if (this.state === HookState.EXTENDING) {
      this.stateData.grabbedItem = item;
      this.transitionTo(HookState.GRABBING);
      // 立即转换到回收状态
      this.transitionTo(HookState.RETRACTING);
      return true;
    }
    return false;
  }

  // 计算回收速度（受物品重量影响）
  private getRetractSpeed(): number {
    const item = this.stateData.grabbedItem;
    if (!item) {
      return this.config.retractSpeedBase;
    }
    // 重量越大，速度越慢
    const weightFactor = Math.max(0.3, 1 - (item.weight * 0.1));
    return this.config.retractSpeedBase * weightFactor;
  }

  // 更新钩子位置（基于当前角度和长度）
  private updatePosition(): void {
    const radian = (this.stateData.angle * Math.PI) / 180;
    this.stateData.position = {
      x: this.origin.x + Math.cos(radian) * this.stateData.length,
      y: this.origin.y + Math.sin(radian) * this.stateData.length
    };
  }

  // 主更新循环
  public update(deltaTime: number): void {
    switch (this.state) {
      case HookState.IDLE:
        this.updateIdle(deltaTime);
        break;
      case HookState.EXTENDING:
        this.updateExtending(deltaTime);
        break;
      case HookState.RETRACTING:
        this.updateRetracting(deltaTime);
        break;
      case HookState.COOLDOWN:
        this.updateCooldown(deltaTime);
        break;
    }
  }

  // 空闲状态更新 - 摆动
  private updateIdle(deltaTime: number): void {
    const swingRange = this.config.swingAngleRange;
    const currentAngle = this.stateData.angle;

    // 在 -90 ± swingRange/2 范围内摆动
    const minAngle = -90 - swingRange / 2;
    const maxAngle = -90 + swingRange / 2;

    let newAngle = currentAngle + this.config.swingSpeed * this.stateData.swingDirection * deltaTime;

    // 边界检测和反弹
    if (newAngle >= maxAngle) {
      newAngle = maxAngle;
      this.stateData.swingDirection = -1;
    } else if (newAngle <= minAngle) {
      newAngle = minAngle;
      this.stateData.swingDirection = 1;
    }

    this.stateData.angle = newAngle;
    this.stateData.length = 0;
    this.updatePosition();
  }

  // 伸出状态更新
  private updateExtending(deltaTime: number): void {
    this.stateData.length += this.config.extendSpeed * deltaTime;

    // 检查是否达到最大长度
    if (this.stateData.length >= this.config.maxLength) {
      this.stateData.length = this.config.maxLength;
      this.transitionTo(HookState.RETRACTING);
    }

    this.updatePosition();
  }

  // 回收状态更新
  private updateRetracting(deltaTime: number): void {
    const retractSpeed = this.getRetractSpeed();
    this.stateData.length -= retractSpeed * deltaTime;

    // 检查是否回到起点
    if (this.stateData.length <= 0) {
      this.stateData.length = 0;
      this.stateData.grabbedItem = null;
      this.transitionTo(HookState.COOLDOWN);
    }

    this.updatePosition();
  }

  // 冷却状态更新
  private updateCooldown(deltaTime: number): void {
    const elapsed = Date.now() - this.stateData.stateStartTime;

    if (elapsed >= this.config.cooldownDuration) {
      this.transitionTo(HookState.IDLE);
    }
  }

  // 获取钩子末端位置（用于碰撞检测）
  public getHookTip(): Position {
    return { ...this.stateData.position };
  }

  // 获取绳索起点和终点（用于渲染）
  public getRopeLine(): { start: Position; end: Position } {
    return {
      start: { ...this.origin },
      end: { ...this.stateData.position }
    };
  }

  // 是否正在抓取中
  public isBusy(): boolean {
    return this.state !== HookState.IDLE && this.state !== HookState.COOLDOWN;
  }

  // 重置状态机
  public reset(): void {
    this.state = HookState.IDLE;
    this.stateData = {
      state: HookState.IDLE,
      position: { ...this.origin },
      angle: -90,
      length: 0,
      grabbedItem: null,
      stateStartTime: Date.now(),
      swingDirection: 1
    };
  }

  // 获取当前抓取的物品
  public getGrabbedItem(): GrabbedItem | null {
    return this.stateData.grabbedItem;
  }

  // 获取状态持续时间
  public getStateDuration(): number {
    return Date.now() - this.stateData.stateStartTime;
  }

  // 序列化状态（用于存档）
  public serialize(): object {
    return {
      state: this.state,
      stateData: {
        ...this.stateData,
        grabbedItem: this.stateData.grabbedItem ? { ...this.stateData.grabbedItem } : null
      },
      config: { ...this.config },
      origin: { ...this.origin }
    };
  }

  // 反序列化状态
  public deserialize(data: any): void {
    this.state = data.state;
    this.stateData = {
      ...data.stateData,
      grabbedItem: data.stateData.grabbedItem
    };
    this.config = { ...data.config };
    this.origin = { ...data.origin };
  }
}

// 使用示例
export function createHookStateMachineExample(): void {
  // 创建钩子状态机
  const hook = new HookStateMachine(
    { x: 400, y: 100 }, // 起点位置
    {
      maxLength: 400,
      extendSpeed: 8,
      retractSpeedBase: 10,
      swingSpeed: 1.5,
      swingAngleRange: 90,
      cooldownDuration: 300
    }
  );

  // 监听状态变化
  hook.onStateChange((from, to, data) => {
    console.log(`State changed: ${from} -> ${to}`);
    console.log(`Angle: ${data.angle.toFixed(2)}, Length: ${data.length.toFixed(2)}`);
  });

  // 模拟游戏循环
  let lastTime = Date.now();

  function gameLoop() {
    const currentTime = Date.now();
    const deltaTime = (currentTime - lastTime) / 1000; // 转换为秒
    lastTime = currentTime;

    // 更新钩子状态机
    hook.update(deltaTime);

    // 渲染钩子（伪代码）
    // renderHook(hook.getRopeLine(), hook.getHookTip());

    requestAnimationFrame(gameLoop);
  }

  // 启动游戏循环
  // gameLoop();
}
